import{_ as d,o as e,c as a,a6 as r}from"./chunks/framework.BBIckNDn.js";const p=JSON.parse('{"title":"第3部: GoFデザインパターン","description":"","frontmatter":{"title":"第3部: GoFデザインパターン","study":{"source":"C++ Wiki","kind":"索引","status":"既存原稿","summary":"デザインパターンは、繰り返し現れる設計問題への定型解のカタログです。GoF(Gang of Four: Gamma, Helm, Johnson, Vlissides)の23パターンが古典として整理されています。"}},"headers":[],"relativePath":"design/patterns/index.md","filePath":"design/patterns/index.md"}'),s={name:"design/patterns/index.md"};function n(o,t,h,i,l,m){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第3部-gofデザインパターン" tabindex="-1">第3部: GoFデザインパターン <a class="header-anchor" href="#第3部-gofデザインパターン" aria-label="Permalink to &quot;第3部: GoFデザインパターン&quot;">​</a></h1><p>デザインパターンは、繰り返し現れる設計問題への<strong>定型解のカタログ</strong>です。GoF(Gang of Four: Gamma, Helm, Johnson, Vlissides)の23パターンが古典として整理されています。</p><h2 id="パターンを学ぶ目的-重要" tabindex="-1">パターンを学ぶ目的(重要) <a class="header-anchor" href="#パターンを学ぶ目的-重要" aria-label="Permalink to &quot;パターンを学ぶ目的(重要)&quot;">​</a></h2><p>パターン名を暗記することではなく、<strong>「この問題には、どんな選択肢があり、なぜこの構造を選ぶのか」を判断できる</strong>ようになることが目的です。各ページは必ず「パターンなしの実装 → 問題点 → 適用 → 失うもの → 使わない場面」の順で書かれています。「使わない場面」まで読んで1ページです。</p><ul><li>パターンは<strong>発明ではなく発見</strong>: 優れたコードに繰り返し現れた形に名前を付けたもの。名前は会話の道具(「ここObserverでいいよね」)として最も価値があります。</li><li>パターンは<strong>絶対規則ではない</strong>: 適用すること自体に価値はなく、問題がないところに適用すればただの複雑化です。</li><li>言語で形は変わる: GoF本はC++/Smalltalk時代のもの。C++20ではラムダや<code>std::function</code>、テンプレートで簡潔になるパターンが多く、各ページで現代的な形も示します。</li></ul><h2 id="_3分類" tabindex="-1">3分類 <a class="header-anchor" href="#_3分類" aria-label="Permalink to &quot;3分類&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分類</th><th>何を扱うか</th><th>直感</th></tr></thead><tbody><tr><td><strong>生成 (Creational)</strong></td><td>オブジェクトを「誰が・どうやって」作るか</td><td><code>new</code> を直接書くと生成方法に結合する。生成の柔軟性が欲しいときの道具</td></tr><tr><td><strong>構造 (Structural)</strong></td><td>クラス・オブジェクトを「どう組み合わせて」大きな構造を作るか</td><td>包む・繋ぐ・まとめる。既存のものを変えずに形を合わせる道具</td></tr><tr><td><strong>振る舞い (Behavioral)</strong></td><td>オブジェクト間の「責任分担と通信」をどうするか</td><td>誰が何を決め、どう伝えるか。アルゴリズムと通知の道具</td></tr></tbody></table><h2 id="生成パターン" tabindex="-1">生成パターン <a class="header-anchor" href="#生成パターン" aria-label="Permalink to &quot;生成パターン&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パターン</th><th>一言で</th><th>ゲームでの典型</th></tr></thead><tbody><tr><td><a href="/study/design/patterns/factory-method.html">Factory Method</a></td><td>生成をサブクラス/関数に任せる</td><td>敵の生成をステージ毎に変える</td></tr><tr><td><a href="/study/design/patterns/abstract-factory.html">Abstract Factory</a></td><td>関連する一族をまとめて生成</td><td>プラットフォーム別UI部品一式</td></tr><tr><td><a href="/study/design/patterns/builder.html">Builder</a></td><td>複雑な構築を段階的に</td><td>キャラクターメイキング、レベル構築</td></tr><tr><td><a href="/study/design/patterns/prototype.html">Prototype</a></td><td>見本のコピーで生成</td><td>配置済み敵の複製(UnityのPrefabの思想)</td></tr><tr><td><a href="/study/design/patterns/singleton.html">Singleton</a></td><td>唯一のインスタンス+全域アクセス</td><td>各種Manager(乱用注意の筆頭)</td></tr></tbody></table><h2 id="構造パターン" tabindex="-1">構造パターン <a class="header-anchor" href="#構造パターン" aria-label="Permalink to &quot;構造パターン&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パターン</th><th>一言で</th><th>ゲームでの典型</th></tr></thead><tbody><tr><td><a href="/study/design/patterns/adapter.html">Adapter</a></td><td>インターフェースを変換して繋ぐ</td><td>外部SDKを自作インターフェースに合わせる</td></tr><tr><td><a href="/study/design/patterns/bridge.html">Bridge</a></td><td>抽象と実装の2軸を分離</td><td>武器の種類×プラットフォーム描画</td></tr><tr><td><a href="/study/design/patterns/composite.html">Composite</a></td><td>個と集合を同一視</td><td>シーングラフ、UIツリー</td></tr><tr><td><a href="/study/design/patterns/decorator.html">Decorator</a></td><td>包んで機能を足す</td><td>バフでダメージ計算を装飾</td></tr><tr><td><a href="/study/design/patterns/facade.html">Facade</a></td><td>複雑な下位系に窓口を1つ</td><td>サウンド再生の一枚窓口</td></tr><tr><td><a href="/study/design/patterns/flyweight.html">Flyweight</a></td><td>共有できるデータを共有</td><td>弾・木・タイルの共通データ</td></tr><tr><td><a href="/study/design/patterns/proxy.html">Proxy</a></td><td>代理を挟んで制御</td><td>アセットの遅延ロード</td></tr></tbody></table><h2 id="振る舞いパターン" tabindex="-1">振る舞いパターン <a class="header-anchor" href="#振る舞いパターン" aria-label="Permalink to &quot;振る舞いパターン&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パターン</th><th>一言で</th><th>ゲームでの典型</th></tr></thead><tbody><tr><td><a href="/study/design/patterns/chain-of-responsibility.html">Chain of Responsibility</a></td><td>処理者の連鎖に流す</td><td>ダメージ軽減の段階処理、UIイベント伝播</td></tr><tr><td><a href="/study/design/patterns/command.html">Command</a></td><td>操作をオブジェクト化</td><td>入力のリバインド、Undo、リプレイ</td></tr><tr><td><a href="/study/design/patterns/interpreter.html">Interpreter</a></td><td>文法を持つ言語を解釈</td><td>スキルスクリプト、数式パーサ</td></tr><tr><td><a href="/study/design/patterns/iterator.html">Iterator</a></td><td>走査を抽象化</td><td>コンテナ走査(C++ではイテレータとして言語に溶けている)</td></tr><tr><td><a href="/study/design/patterns/mediator.html">Mediator</a></td><td>多対多の通信を仲介役に集約</td><td>UI画面内の部品間調整</td></tr><tr><td><a href="/study/design/patterns/memento.html">Memento</a></td><td>状態のスナップショットを保存</td><td>セーブ、Undo、リプレイの基準点</td></tr><tr><td><a href="/study/design/patterns/observer.html">Observer</a></td><td>変化を購読者に通知</td><td>イベント通知全般(C#のevent)</td></tr><tr><td><a href="/study/design/patterns/state.html">State</a></td><td>状態ごとの振る舞いをオブジェクト化</td><td>キャラの状態遷移、AI</td></tr><tr><td><a href="/study/design/patterns/strategy.html">Strategy</a></td><td>アルゴリズムを差し替え可能に</td><td>移動アルゴリズム、AI難易度</td></tr><tr><td><a href="/study/design/patterns/template-method.html">Template Method</a></td><td>骨格を親、詳細を子に</td><td>ゲームモードの共通フロー</td></tr><tr><td><a href="/study/design/patterns/visitor.html">Visitor</a></td><td>構造側を変えずに操作を追加</td><td>シーンツリーへの操作追加(使用は稀)</td></tr></tbody></table><p><a href="/study/design/patterns/exercises.html">演習</a> で総仕上げをしてください。</p><h2 id="どう選ぶか-逆引き" tabindex="-1">どう選ぶか(逆引き) <a class="header-anchor" href="#どう選ぶか-逆引き" aria-label="Permalink to &quot;どう選ぶか(逆引き)&quot;">​</a></h2><ul><li>生成方法を差し替えたい・生成に条件がある → Factory Method / Abstract Factory</li><li>「if種類分岐」が増え続ける → State / Strategy / ポリモーフィズム全般</li><li>通知したいが相手を知りたくない → Observer(即時)/ <a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue</a>(遅延)</li><li>操作を記録・取消・再生したい → Command (+ Memento)</li><li>既存コードを変えずに機能追加 → Decorator / Proxy / Adapter</li><li>大量の同種オブジェクトでメモリが苦しい → Flyweight (+ <a href="/study/game/patterns/object-pool.html">Object Pool</a>)</li><li>詳しくは <a href="/study/design/decisions/abstraction-and-patterns.html">判断ガイド: デザインパターンを使うべきか</a></li></ul><hr><p><a href="/study/guide/cpp-index.html">全体目次</a> | 次: <a href="/study/design/patterns/factory-method.html">Factory Method</a></p>',18)])])}const g=d(s,[["render",n]]);export{p as __pageData,g as default};
